//! CC 5.3.3.10 E1 per-frame link seal, frame version 0x02 with key phases.
//!
//! `vectors/transit/transit_seal_frame_v2_v1.json` was generated by
//! `vectors/transit/gen.py`, written from `docs/TRANSIT_HANDSHAKE_V2.md`
//! independently of `ciris_crypto::transit` (pyca AES-GCM, its own HKDF). Its
//! keys are the first-contact handshake's and the promotion's in
//! `transit_ctkx_v2_v1.json`, so the two files chain. Every sequence is
//! replayed through [`seal_frame`] and one [`FrameOpener`]: each frame must be
//! byte-identical and each outcome must match.
#![cfg(feature = "transit")]

use ciris_crypto::transit::{
    link_seal_key, seal_frame, FrameError, FrameOpener, Lane, OpenOutcome, Role,
};
use serde_json::Value;

const SEAL: &str = include_str!("vectors/transit/transit_seal_frame_v2_v1.json");
const CTKX: &str = include_str!("vectors/transit/transit_ctkx_v2_v1.json");

fn json(s: &str) -> Value {
    serde_json::from_str(s).expect("vector file is JSON")
}

fn h(v: &Value) -> Vec<u8> {
    hex::decode(v.as_str().expect("hex string")).expect("hex")
}

fn arr<const N: usize>(v: &Value) -> [u8; N] {
    h(v).try_into().expect("length")
}

fn lane(name: &str) -> Lane {
    match name {
        "channel" => Lane::Channel,
        "resource" => Lane::Resource,
        "request" => Lane::Request,
        "response" => Lane::Response,
        "datagram" => Lane::Datagram,
        other => panic!("unknown lane {other}"),
    }
}

fn u(v: &Value) -> u64 {
    v.as_u64().expect("integer")
}

fn error_code(e: FrameError) -> &'static str {
    e.code()
}

struct Keys {
    link_id: [u8; 16],
    /// `[phase][0 = i2r, 1 = r2i]`.
    k: [[[u8; 32]; 2]; 2],
}

impl Keys {
    /// The key the PEER of `receiver` seals with at `phase`.
    fn peer_seal(&self, receiver: Role, phase: usize) -> &[u8; 32] {
        match receiver {
            Role::Responder => &self.k[phase][0],
            Role::Initiator => &self.k[phase][1],
        }
    }
}

fn keys(d: &Value) -> Keys {
    let i = &d["inputs"];
    Keys {
        link_id: arr(&i["link_id"]),
        k: [
            [arr(&i["phase0"]["k_i2r"]), arr(&i["phase0"]["k_r2i"])],
            [arr(&i["phase1"]["k_i2r"]), arr(&i["phase1"]["k_r2i"])],
        ],
    }
}

#[test]
fn seal_frame_inputs_chain_to_the_handshake_vectors() {
    let d = json(SEAL);
    let c = json(CTKX);
    let i = &d["inputs"];
    assert_eq!(i["source"], "transit_ctkx_v2_v1.json");
    let hs = c["handshakes"]
        .as_array()
        .unwrap()
        .iter()
        .find(|x| x["name"] == i["handshake"])
        .expect("named handshake");
    let pr = c["promotions"]
        .as_array()
        .unwrap()
        .iter()
        .find(|x| x["name"] == i["promotion"])
        .expect("named promotion");
    assert_eq!(pr["base"], i["handshake"]);
    assert_eq!(i["link_id"], hs["inputs"]["link_id"]);
    assert_eq!(i["phase0"]["k_i2r"], hs["k_i2r"]);
    assert_eq!(i["phase0"]["k_r2i"], hs["k_r2i"]);
    assert_eq!(i["phase1"]["k_i2r"], pr["k_i2r"]);
    assert_eq!(i["phase1"]["k_r2i"], pr["k_r2i"]);
}

#[test]
fn seal_keys_match() {
    let d = json(SEAL);
    let k = keys(&d);
    for (p, phase) in [(0, "phase0"), (1, "phase1")] {
        for (j, dir) in [(0, "i2r"), (1, "r2i")] {
            let got = link_seal_key(&k.k[p][j], &k.link_id);
            assert_eq!(
                &got[..],
                h(&d["seal_keys"][format!("{phase}_{dir}")]).as_slice(),
                "{phase}_{dir}"
            );
        }
    }
}

/// Rebuild a step's frame from its `sealed` inputs (and `tamper`), and check
/// it against the recorded bytes.
fn rebuild(k: &Keys, receiver: Role, step: &Value, name: &str) -> Vec<u8> {
    let recorded = h(&step["frame"]);
    let Some(s) = step.get("sealed") else {
        return recorded;
    };
    let phase = u8::try_from(u(&s["phase"])).unwrap();
    let key_phase = s.get("key_phase").map_or(u64::from(phase), u);
    let seal_lane = lane(
        s.get("lane")
            .and_then(Value::as_str)
            .unwrap_or_else(|| step["lane"].as_str().unwrap()),
    );
    let mut frame = seal_frame(
        k.peer_seal(receiver, usize::try_from(key_phase).unwrap()),
        &k.link_id,
        seal_lane,
        phase,
        u(&s["counter"]),
        &h(&s["plaintext"]),
    );
    if let Some(t) = step.get("tamper") {
        if let Some(x) = t.get("xor") {
            let off = usize::try_from(u(&x[0])).unwrap();
            frame[off] ^= u8::try_from(u(&x[1])).unwrap();
        }
        if let Some(x) = t.get("set") {
            let off = usize::try_from(u(&x[0])).unwrap();
            frame[off] = u8::try_from(u(&x[1])).unwrap();
        }
        if let Some(n) = t.get("truncate_to") {
            frame.truncate(usize::try_from(u(n)).unwrap());
        }
    }
    assert_eq!(
        hex::encode(&frame),
        hex::encode(&recorded),
        "{name}: frame bytes"
    );
    frame
}

#[test]
fn every_sequence_replays() {
    let d = json(SEAL);
    let k = keys(&d);
    let seqs = d["sequences"].as_array().unwrap();
    assert!(seqs.len() >= 20, "sequences: {}", seqs.len());
    let mut sealed_frames = 0usize;
    for seq in seqs {
        let name = seq["name"].as_str().unwrap();
        let receiver = match seq["receiver"].as_str().unwrap() {
            "responder" => Role::Responder,
            "initiator" => Role::Initiator,
            other => panic!("{name}: receiver {other}"),
        };
        let mut opener = FrameOpener::new(receiver, &k.k[0][0], &k.k[0][1], &k.link_id);
        let steps = seq["steps"].as_array().unwrap();
        for (n, step) in steps.iter().enumerate() {
            let at = format!("{name} step {n}");
            let expect = step["expect"].as_str().unwrap();
            let result: Result<Option<OpenOutcome>, FrameError> = match step["op"].as_str().unwrap()
            {
                "open" => {
                    if step.get("sealed").is_some() {
                        sealed_frames += 1;
                    }
                    let frame = rebuild(&k, receiver, step, &at);
                    opener
                        .open(lane(step["lane"].as_str().unwrap()), &frame)
                        .map(Some)
                },
                "promote" => opener.promote(&k.k[1][0], &k.k[1][1]).map(|()| None),
                "retire_phase0" => {
                    opener.retire_phase0();
                    Ok(None)
                },
                other => panic!("{at}: op {other}"),
            };
            match (expect, result) {
                ("ok", Ok(None)) => {},
                ("plaintext", Ok(Some(OpenOutcome::Plaintext(pt)))) => {
                    assert_eq!(pt, h(&step["plaintext"]), "{at}: plaintext");
                },
                ("dropped_stale", Ok(Some(OpenOutcome::DroppedStale)))
                | ("dropped_replay", Ok(Some(OpenOutcome::DroppedReplay))) => {},
                ("close", Err(e)) => {
                    assert_eq!(
                        error_code(e),
                        step["error"].as_str().unwrap(),
                        "{at}: error"
                    );
                    assert_eq!(n, steps.len() - 1, "{at}: a close ends the sequence");
                },
                (want, got) => panic!("{at}: expected {want}, got {got:?}"),
            }
        }
        assert_eq!(
            opener.seal_stale_phase(),
            u(&seq["seal_stale_phase"]),
            "{name}: seal_stale_phase"
        );
        assert_eq!(
            opener.seal_dropped_replay(),
            u(&seq["seal_dropped_replay"]),
            "{name}: seal_dropped_replay"
        );
    }
    assert!(
        sealed_frames >= 40,
        "sealed frames reproduced: {sealed_frames}"
    );
}

#[test]
fn lane_bytes_are_the_doc_s() {
    for (b, l) in (1u8..=5).zip(Lane::ALL) {
        assert_eq!(l.as_u8(), b);
        assert_eq!(Lane::from_u8(b), Some(l));
    }
    assert_eq!(Lane::from_u8(0), None);
    assert_eq!(Lane::from_u8(6), None);
}
